mapper.update:
UPDATE account
SET status = #{status}, updated_at = CURRENT_TIMESTAMP, version = version + 1
WHERE id = #{id, typeHandler=com.zija.system.internal.persistence.PostgresUuidTypeHandler}
  AND version = #{version}

UPDATE account
SET password_hash = #{passwordHash}, updated_at = CURRENT_TIMESTAMP, version = version + 1
WHERE id = #{id, typeHandler=com.zija.system.internal.persistence.PostgresUuidTypeHandler}
  AND version = #{version}
